# Generated by forge. The types engine for Python (SPECS §15): a daemon that keeps ty's
# language server running for one repository and answers the hooks' type questions
# through a FIFO. Started by forge_types_up as
#   uvx --python <py> --from ty==<pin> python types_python.py <root> <state-dir>
# so ty is the pinned one next to this interpreter. It detaches (its own session, so
# the hook that started it can end), then writes "ready <server> <version>" (or
# "failed <reason>") to the FIFO <state-dir>/started.
#
# <state-dir>/in is a FIFO of lines (each shorter than PIPE_BUF, so writers never mix):
#   changed<TAB><path>   a file changed on disk (relative to the root): resynced
#   restart | stop       the daemon exits (restart: the dependencies changed; the next
#                        use starts it again); "stop<TAB><dir>" answers "end" in the FIFO
#                        <dir>/reply once its language server has exited
#   <absolute dir>       a question: <dir>/req holds ast-grep --json=stream matches whose
#                        metadata has forge_where; the answer goes to the FIFO <dir>/reply:
#                        the matches whose forge_where holds (verbatim), "error<TAB>..."
#                        lines, then "end"
# The daemon exits after FORGE_TYPES_IDLE seconds (1800) without a line, and when its
# state directory or the repository is gone or another daemon took the state directory
# over (checked every 10 seconds).
import json
import os
import re
import select
import subprocess
import sys
import threading
import time
from urllib.parse import quote, unquote

ROOT = os.path.realpath(sys.argv[1])
STATE = sys.argv[2]
IDLE = int(os.environ.get("FORGE_TYPES_IDLE", "1800"))
TY = os.path.join(os.path.dirname(sys.executable), "ty")
LOG = open(os.path.join(STATE, "log"), "a", buffering=1)


def log(*a):
    LOG.write(time.strftime("%H:%M:%S ") + " ".join(str(x) for x in a) + "\n")


def uri(path):
    return "file://" + quote(os.path.realpath(path))


def path_of(u):
    return unquote(u[len("file://"):]) if u.startswith("file://") else u


def u16(s):
    return len(s.encode("utf-16-le")) // 2


def position(text, index):
    """The LSP position (UTF-16 columns) of a str index."""
    line = text.count("\n", 0, index)
    start = text.rfind("\n", 0, index) + 1
    return {"line": line, "character": u16(text[start:index])}


def index_of(text, pos):
    """The str index of an LSP position."""
    i = 0
    for _ in range(pos["line"]):
        i = text.index("\n", i) + 1
    col, j = 0, i
    while col < pos["character"] and j < len(text) and text[j] != "\n":
        col += 2 if ord(text[j]) > 0xFFFF else 1
        j += 1
    return j


# ---------------------------------------------------------------- the language server


class Slot:
    """A request waiting for its response."""

    def __init__(self):
        self.done = threading.Event()
        self.response = {}


class Server:
    def __init__(self):
        self.proc = subprocess.Popen([TY, "server"], cwd=ROOT, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=LOG)
        assert self.proc.stdin is not None and self.proc.stdout is not None
        self.stdin, self.stdout = self.proc.stdin, self.proc.stdout
        self.next = 0
        self.lock = threading.Lock()
        self.waiting = {}
        self.versions = {}
        self.texts = {}
        self.stopping = False
        threading.Thread(target=self.read, daemon=True).start()

    def send(self, msg):
        body = json.dumps(msg).encode()
        with self.lock:
            self.stdin.write(b"Content-Length: %d\r\n\r\n" % len(body) + body)
            self.stdin.flush()

    def read(self):
        try:
            self.read_messages()
        except Exception as e:  # noqa: BLE001 - a broken stream is the server ending
            if not self.stopping:
                log("server stream broken:", repr(e))
                os._exit(3)

    def read_messages(self):
        out = self.stdout
        while True:
            length = None
            while True:
                line = out.readline()
                if not line:
                    if self.stopping:
                        return
                    log("server exited")
                    os._exit(3)
                if line in (b"\r\n", b"\n"):
                    break
                if line.lower().startswith(b"content-length:"):
                    length = int(line.split(b":")[1])
            if length is None:
                continue
            msg = json.loads(out.read(length))
            if "method" in msg and "id" in msg:
                # a request from the server (configuration, registrations): answer with defaults
                items = (msg.get("params") or {}).get("items")
                self.send({"jsonrpc": "2.0", "id": msg["id"], "result": [None] * len(items) if items else None})
            elif "id" in msg:
                slot = self.waiting.pop(msg["id"], None)
                if slot:
                    slot.response = msg
                    slot.done.set()

    def request(self, method, params):
        """Sends a request; returns a function that waits for its result."""
        with self.lock:
            self.next += 1
            rid = self.next
        slot = Slot()
        self.waiting[rid] = slot
        self.send({"jsonrpc": "2.0", "id": rid, "method": method, "params": params})

        def wait():
            slot.done.wait(60)
            return slot.response.get("result")

        return wait

    def notify(self, method, params):
        self.send({"jsonrpc": "2.0", "method": method, "params": params})

    def start(self):
        info = self.request(
            "initialize",
            {
                "processId": os.getpid(),
                "rootUri": uri(ROOT),
                "workspaceFolders": [{"uri": uri(ROOT), "name": "root"}],
                "capabilities": {
                    "general": {"positionEncodings": ["utf-16"]},
                    "textDocument": {"typeDefinition": {"linkSupport": True}, "definition": {"linkSupport": True}, "typeHierarchy": {}},
                    "workspace": {"configuration": True, "workspaceFolders": True},
                },
            },
        )()
        self.notify("initialized", {})
        server = (info or {}).get("serverInfo") or {}
        return "%s %s" % (server.get("name", "ty"), (server.get("version") or "").split(" ")[0])

    def show(self, path, text):
        """Makes the server see <text> as the content of <path> (in memory only)."""
        u = uri(path)
        v = self.versions.get(u, 0) + 1
        self.versions[u] = v
        if v == 1:
            self.notify("textDocument/didOpen", {"textDocument": {"uri": u, "languageId": "python", "version": v, "text": text}})
        else:
            self.notify("textDocument/didChange", {"textDocument": {"uri": u, "version": v}, "contentChanges": [{"text": text}]})

    def sync(self, path):
        """The file as it is on disk; returns its text."""
        with open(path, encoding="utf-8", errors="surrogateescape") as f:
            text = f.read()
        if self.texts.get(path) != text:
            self.show(path, text)
            self.texts[path] = text
        return text

    def changed(self, path):
        if uri(path) in self.versions:
            if os.path.exists(path):
                self.sync(path)
            return
        kind = 2 if os.path.exists(path) else 3
        self.notify("workspace/didChangeWatchedFiles", {"changes": [{"uri": uri(path), "type": kind}]})


# ---------------------------------------------------------------- declarations


def declared_in(path):
    """(package, module) of a declaration file: the import package and dotted module
    under site-packages (a -stubs package counts as its package), typeshed's stdlib or
    third-party stubs; (None, module) for the project's own files."""
    p = path.replace(os.sep, "/")
    rel = None
    for marker in ("/site-packages/", "/dist-packages/"):
        i = p.rfind(marker)
        if i >= 0:
            rel = p[i + len(marker):]
            break
    if rel is None:
        i = p.rfind("/typeshed/")
        if i >= 0:
            rest = p[i + len("/typeshed/"):].split("/")
            if "stdlib" in rest:
                rel = "/".join(rest[rest.index("stdlib") + 1:])
            elif "stubs" in rest:
                rel = "/".join(rest[rest.index("stubs") + 2:])
    project = False
    if rel is None:
        real = os.path.realpath(path)
        if not real.startswith(ROOT + "/"):
            return (None, None)
        rel = real[len(ROOT) + 1:]
        if rel.startswith("src/"):
            rel = rel[4:]
        project = True
    segs = [s for s in re.sub(r"\.pyi?$", "", rel).split("/") if s]
    if segs and segs[-1] == "__init__":
        segs.pop()
    if not segs:
        return (None, None)
    segs[0] = re.sub(r"-stubs$", "", segs[0])
    module = ".".join(segs)
    return (None if project else segs[0], module)


def word_at(path, pos):
    try:
        with open(path, encoding="utf-8", errors="surrogateescape") as f:
            text = f.read()
    except OSError:
        return None
    i = index_of(text, pos)
    m = re.compile(r"[A-Za-z_][A-Za-z0-9_]*").search(text, i)
    while m and m.group(0) in ("class", "def", "type", "async"):
        m = re.compile(r"[A-Za-z_][A-Za-z0-9_]*").search(text, m.end())
    return m.group(0) if m else None


class Types:
    def __init__(self, server):
        self.server = server
        self.cache = {}  # declaration location outside the project -> its declarations with supertypes

    def hierarchy(self, loc):
        """The declarations (package, module, name) of the type declared at loc and of its
        supertypes, through the server's type hierarchy."""
        key = (loc["uri"], loc["pos"]["line"], loc["pos"]["character"])
        if key in self.cache:
            return self.cache[key]
        out, seen = set(), set()
        items = self.server.request("textDocument/prepareTypeHierarchy", {"textDocument": {"uri": loc["uri"]}, "position": loc["pos"]})() or []
        if not items:
            name = word_at(path_of(loc["uri"]), loc["pos"])
            pkg, mod = declared_in(path_of(loc["uri"]))
            out.add((pkg, mod, name))
        todo = list(items)
        while todo and len(seen) < 64:
            item = todo.pop()
            k = (item["uri"], item["selectionRange"]["start"]["line"], item["selectionRange"]["start"]["character"])
            if k in seen:
                continue
            seen.add(k)
            pkg, mod = declared_in(path_of(item["uri"]))
            out.add((pkg, mod, item["name"]))
            todo.extend(self.server.request("typeHierarchy/supertypes", {"item": item})() or [])
        if not path_of(loc["uri"]).startswith(ROOT + "/") or "/site-packages/" in loc["uri"]:
            self.cache[key] = out
        return out

    def check(self, path, wanted):
        """wanted: [(match index, variable, start byte, end byte)]. Returns
        {(match index, variable): set of declarations}, from the type the server infers
        for each expression: the file is shown to the server with each expression
        bound to a fresh name ((__forge_t<i> := (<expr>))), in memory only, and the type
        definition of that name is asked; then the file is shown as it is."""
        text = self.server.sync(path)
        raw = text.encode("utf-8", errors="surrogateescape")
        # one fresh name per distinct expression range
        ranges, slot = [], []
        for _, _, s, e in wanted:
            r = (len(raw[:s].decode("utf-8", errors="surrogateescape")), len(raw[:e].decode("utf-8", errors="surrogateescape")))
            if r not in ranges:
                ranges.append(r)
            slot.append(ranges.index(r))
        # inserts: at each start the opening, at each end the closing; at the same offset,
        # closings first (inner first), then openings (outer first)
        events = []
        for n, (s, e) in enumerate(ranges):
            events.append((s, 1, -(e - s), n, "(__forge_t%d := (" % n))
            events.append((e, 0, e - s, n, "))"))
        events.sort()
        out, last, anchors = [], 0, {}
        for off, kind, _, n, piece in events:
            out.append(text[last:off])
            last = off
            if kind == 1:
                anchors[n] = sum(len(x) for x in out) + 1 + 2  # inside the name
            out.append(piece)
        out.append(text[last:])
        overlay = "".join(out)
        self.server.show(path, overlay)
        waits = [
            self.server.request("textDocument/typeDefinition", {"textDocument": {"uri": uri(path)}, "position": position(overlay, anchors[n])})
            for n in range(len(ranges))
        ]
        results = [w() for w in waits]
        self.server.show(path, text)
        per_range = []
        for r in results:
            decls = set()
            for l in (r if isinstance(r, list) else [r] if r else []):
                u = l.get("targetUri") or l.get("uri")
                rg = l.get("targetSelectionRange") or l.get("targetRange") or l.get("range")
                decls |= self.hierarchy({"uri": u, "pos": rg["start"]})
            # Any and Unknown (an unannotated parameter, an unresolved import) say nothing
            unknown = all(d[0] == "typing" and d[2] == "Any" or (d[1] or "").startswith("ty_extensions") for d in decls)
            per_range.append((frozenset(decls), unknown))
        return {(w[0], w[1]): per_range[slot[n]] for n, w in enumerate(wanted)}


# ---------------------------------------------------------------- constraints


def listed(v):
    return None if v is None else v if isinstance(v, list) else [v]


def satisfies(found, spec):
    """A type spec ({package, module, name, unknown}) holds when one declaration of the
    type (a union member, or a supertype of one) is declared there with that name; a
    type the checker does not know (Any, Unknown) holds only with unknown: match."""
    decls, unknown = found
    if unknown:
        return spec.get("unknown") == "match"
    pkgs, mods, names = listed(spec.get("package")), listed(spec.get("module")), listed(spec.get("name"))
    for pkg, mod, name in decls:
        if pkgs is not None and pkg not in pkgs:
            continue
        if mods is not None and not any(mod == m or (mod or "").startswith(m + ".") for m in mods):
            continue
        if names is not None and name not in names:
            continue
        return True
    return False


def holds(found, cond):
    if "not" in cond:
        return not holds(found, cond["not"])
    return satisfies(found, cond["type"])


def answer(types, matches):
    """The matches whose forge_where holds."""
    by_file = {}
    for n, m in enumerate(matches):
        where = (m.get("metadata") or {}).get("forge_where") or {}
        single = (m.get("metaVariables") or {}).get("single") or {}
        for var in where:
            if var in single:
                b = single[var]["range"]["byteOffset"]
                by_file.setdefault(m["file"], []).append((n, var, b["start"], b["end"]))
    found = {}
    for f, wanted in by_file.items():
        found.update(types.check(os.path.join(ROOT, f), wanted))
    keep = []
    for n, m in enumerate(matches):
        where = (m.get("metadata") or {}).get("forge_where") or {}
        if all((n, var) not in found or holds(found[(n, var)], cond) for var, cond in where.items()):
            keep.append(n)
    return keep


# ---------------------------------------------------------------- the FIFO loop


def reply(d, lines):
    try:
        fd = os.open(os.path.join(d, "reply"), os.O_WRONLY | os.O_NONBLOCK)
    except OSError:
        return  # nobody waits for it
    os.set_blocking(fd, True)
    os.write(fd, "".join(l + "\n" for l in lines + ["end"]).encode("utf-8", errors="surrogateescape"))
    os.close(fd)


def orphaned(fd):
    """The state directory was dropped (its FIFO is gone or replaced), another daemon took
    it over (its pid file names that one: a start whose starter was killed can race with
    the next start, and both open the same FIFO) or the repository no longer exists:
    nobody reaches this daemon any more."""
    try:
        with open(os.path.join(STATE, "pid")) as f:
            mine = f.read().strip() == str(os.getpid())
        return not mine or os.stat(os.path.join(STATE, "in")).st_ino != os.fstat(fd).st_ino or not os.path.isdir(ROOT)
    except OSError:
        return True


def serve(server, types, fd):
    buf = b""
    last = checked = time.time()
    # non-blocking: a FIFO another daemon also reads (see orphaned) can be readable for
    # select and empty for read
    os.set_blocking(fd, False)
    while True:
        r, _, _ = select.select([fd], [], [], min(IDLE, 10))
        now = time.time()
        # every 10 seconds, whether lines come or not
        if now - checked >= 10 or not r:
            checked = now
            if orphaned(fd):
                log("orphaned, exiting")
                return
        if not r:
            if now - last >= IDLE:
                log("idle, exiting")
                return
            continue
        try:
            data = os.read(fd, 65536)
        except BlockingIOError:
            continue
        last = now
        buf += data
        while b"\n" in buf:
            line, buf = buf.split(b"\n", 1)
            line = line.decode("utf-8", errors="surrogateescape")
            if line.startswith("changed\t"):
                server.changed(os.path.join(ROOT, line[8:]))
            elif line == "restart" or line == "stop" or line.startswith("stop\t"):
                # "stop<TAB><dir>": answered in <dir>/reply once the server has exited
                log("asked to", line.split("\t")[0])
                return line[5:] if line.startswith("stop\t") else None
            elif line.startswith("/"):
                question(types, line)


def question(types, d):
    try:
        with open(os.path.join(d, "req"), encoding="utf-8", errors="surrogateescape") as f:
            req = f.read().splitlines()
    except OSError:
        return
    matches, raw, out = [], [], []
    for l in req:
        try:
            matches.append(json.loads(l))
            raw.append(l)
        except ValueError:
            out.append("error\tunreadable match: " + l[:80])
    t = time.time()
    try:
        out.extend(raw[n] for n in answer(types, matches))
    except Exception as e:  # noqa: BLE001 - reported to the hook, which fails visibly
        log("error", repr(e))
        out.append("error\t%s: %s" % (type(e).__name__, e))
    log("answered %d matches in %.1f ms" % (len(matches), (time.time() - t) * 1000))
    reply(d, out)


def started(line):
    """Tells the starter (waiting on <state>/started) how the start went."""
    try:
        fd = os.open(os.path.join(STATE, "started"), os.O_WRONLY | os.O_NONBLOCK)
    except OSError:
        return
    os.write(fd, (line + "\n").encode())
    os.close(fd)


def main():
    # detach: a session of its own, so ending the hook that started it does not end it
    if os.fork() > 0:
        os._exit(0)
    os.setsid()
    with open(os.path.join(STATE, "pid"), "w") as f:
        f.write("%d\n" % os.getpid())
    fd = os.open(os.path.join(STATE, "in"), os.O_RDWR)
    server = None
    waiting = None
    try:
        server = Server()
        ready = server.start()
        with open(os.path.join(STATE, "ready"), "w") as f:
            f.write(ready + "\n")
        log("started", ready, "for", ROOT)
        started("ready " + ready)
        waiting = serve(server, Types(server), fd)
    except Exception as e:  # noqa: BLE001 - the starter reports it
        log("failed", repr(e))
        started("failed %s: %s" % (type(e).__name__, e))
    finally:
        if not orphaned(fd):
            for name in ("ready", "pid", "in"):
                try:
                    os.unlink(os.path.join(STATE, name))
                except OSError:
                    pass
        if server:
            server.stopping = True
            try:
                server.request("shutdown", None)
                server.notify("exit", None)
            except OSError:
                pass
            server.proc.terminate()
            try:
                server.proc.wait(5)
            except subprocess.TimeoutExpired:
                server.proc.kill()
        if waiting:
            reply(waiting, [])
        # no interpreter finalization: the reader thread may still hold the server's pipe
        os._exit(0)


main()
